# Trip Page route map

Every Trip Page gets a route map as its FIRST section, above the table of contents, route options, and daily legs. It draws the real driving path of each leg (OSRM geometry), state outlines, markers (start, overnight, destination, gas, scenic detour), one color per leg, a legend, and labels like 'Leg 1 · 334 mi · ≈5 h'. Rebuild it whenever a trip change alters the route, stops, or legs.

## Canvas constraints
- The canvas has no map component and fetches nothing at view time: no map tiles, no remote images. So the map is an inline SVG with route geometry embedded in the page source and fetched at BUILD time by the script below.
- No literal color strings (the typechecker rejects them). Use theme tokens from `useGrokTheme()`. Only three categorical hues exist (c0, c1, c2); use dashes for an alternate route and reuse or dash for a 4th+ leg.
- Keep the viewBox with width 100%, height auto.
- Match the miles and times on the map to the page's tables (use `time_label` per leg to set the time text); say which source you used.
- If you cannot view the live page, say it compiled and typechecked but you could not confirm how it looks.

## Steps
1. Save the script below as `build_map.py` and the component template as `RouteMap.tsx.tpl` in the same folder.
2. Write `trip.json`: `{"title":"...","legs":[{"id":"1","label":"Leg 1","color":"c0","stops":[{"q":"City, ST"},{"q":"City, ST"}],"time_label":"≈5 h"}],"markers":[{"kind":"start|overnight|destination|gas|poi","label":"...","q":"address"}]}`. A place is `{"q":"address"}` (geocoded) or `{"lat":..,"lon":..}` (preferred). Middle stops in a leg become waypoints, which is how an alternate route is forced (give it `"dashed":true,"color":"ink"`). Optional: `label_at` (0-1 along the leg), `label_dx`, `label_dy`; per marker `dx`, `dy`, `anchor`.
3. Run `python3 build_map.py trip.json > route_map.tsx.txt`. Tune label offsets if text collides, then re-run.
4. With EditCanvas: add `useGrokTheme` to the `grok/canvas` import, insert the generated block above `export default function App()`, put `<Section heading="Route map"><RouteMap /></Section>` as the first child of `<Page>`, and list 'Route map' first in the table of contents. EditCanvas typechecks before saving, so a bad edit is rejected.

## build_map.py
```python
#!/usr/bin/env python3
import json, math, sys, time, urllib.parse, urllib.request, os
UA = "atlas-trip-map/1.0 (trip planner)"
OSRM = "https://router.project-osrm.org/route/v1/driving/"
STATES_URL = "https://raw.githubusercontent.com/PublicaMundi/MappingAPI/master/data/geojson/us-states.json"
W = 1000; PAD = 40; HMAX = 900; EPS_ROUTE = 1.2; EPS_STATE = 0.9

def get(url):
    req = urllib.request.Request(url, headers={"User-Agent": UA})
    with urllib.request.urlopen(req, timeout=60) as r:
        return json.load(r)

_last = [0.0]
def geocode(q):
    wait = 1.1 - (time.time() - _last[0])
    if wait > 0: time.sleep(wait)
    _last[0] = time.time()
    res = get("https://nominatim.openstreetmap.org/search?format=json&limit=1&q=" + urllib.parse.quote(q))
    if not res: sys.exit(f"geocode failed for {q!r} - give lat/lon instead")
    return float(res[0]["lat"]), float(res[0]["lon"])

def place(p):
    if "lat" in p: return float(p["lat"]), float(p["lon"])
    return geocode(p["q"])

def route(points):
    coords = ";".join(f"{lon:.6f},{lat:.6f}" for lat, lon in points)
    d = get(f"{OSRM}{coords}?overview=full&geometries=geojson&steps=false")
    if d.get("code") != "Ok": sys.exit(f"OSRM error: {d}")
    r = d["routes"][0]
    return [(c[1], c[0]) for c in r["geometry"]["coordinates"]], r["distance"], r["duration"]

def dp(pts, eps):
    if len(pts) < 3: return pts
    keep = [False] * len(pts); keep[0] = keep[-1] = True
    stack = [(0, len(pts) - 1)]
    while stack:
        a, b = stack.pop()
        ax, ay = pts[a]; bx, by = pts[b]
        dx, dy = bx - ax, by - ay; L = math.hypot(dx, dy) or 1e-9
        mx, mi = -1, -1
        for i in range(a + 1, b):
            px, py = pts[i]
            d = abs(dy * (px - ax) - dx * (py - ay)) / L
            if d > mx: mx, mi = d, i
        if mx > eps:
            keep[mi] = True; stack += [(a, mi), (mi, b)]
    return [p for p, k in zip(pts, keep) if k]

def dp_ring(P, eps):
    if P[0] == P[-1]: P = P[:-1]
    h = len(P) // 2
    return dp(P[:h + 1], eps)[:-1] + dp(P[h:] + [P[0]], eps)[:-1]

def fmt_h(sec):
    m = round(sec / 60); return f"{m // 60} h {m % 60:02d} m"

def main(cfg_path):
    cfg = json.load(open(cfg_path))
    legs, markers = [], []
    for leg in cfg["legs"]:
        pts = [place(s) for s in leg["stops"]]
        geom, dist, dur = route(pts)
        legs.append(dict(leg, geom=geom, dist=dist, dur=dur))
        print(f"{leg['id']}: {dist/1609.344:.0f} mi, {fmt_h(dur)}", file=sys.stderr)
    for m in cfg["markers"]:
        lat, lon = place(m); markers.append(dict(m, lat=lat, lon=lon))
    allpts = [p for l in legs for p in l["geom"]] + [(m["lat"], m["lon"]) for m in markers]
    lat0 = sum(p[0] for p in allpts) / len(allpts)
    k = math.cos(math.radians(lat0))
    xs = [p[1] * k for p in allpts]; ys = [p[0] for p in allpts]
    x0, x1, y0, y1 = min(xs), max(xs), min(ys), max(ys)
    scale = min((W - 2 * PAD) / (x1 - x0), (HMAX - 2 * PAD) / (y1 - y0))
    H = round((y1 - y0) * scale + 2 * PAD) if (y1 - y0) * scale + 2 * PAD > HMAX * 0.6 else round(HMAX * 0.6)
    ox = (W - (x1 - x0) * scale) / 2
    def proj(lat, lon): return ((lon * k - x0) * scale + ox, (y1 - lat) * scale + PAD)
    st = get(STATES_URL); rings = []
    for f in st["features"]:
        g = f["geometry"]; polys = g["coordinates"] if g["type"] == "MultiPolygon" else [g["coordinates"]]
        for poly in polys:
            P = [proj(lat, lon) for lon, lat in poly[0]]
            if any(-60 < x < W + 60 and -60 < y < H + 60 for x, y in P):
                rings.append(dp_ring(P, EPS_STATE))
    def path_d(P): return "M" + "L".join(f"{x:.1f} {y:.1f}" for x, y in P)
    out = dict(width=W, height=H, states=[path_d(r) + "Z" for r in rings], legs=[], markers=[])
    for l in legs:
        P = dp([proj(la, lo) for la, lo in l["geom"]], EPS_ROUTE)
        seg = [math.dist(P[i], P[i + 1]) for i in range(len(P) - 1)]; tot = sum(seg); t = tot * l.get("label_at", .5); acc = 0
        lx, ly = P[0]
        for i, s in enumerate(seg):
            if acc + s >= t:
                f = (t - acc) / (s or 1); lx = P[i][0] + f * (P[i + 1][0] - P[i][0]); ly = P[i][1] + f * (P[i + 1][1] - P[i][1]); break
            acc += s
        out["legs"].append(dict(id=l["id"], label=l["label"], color=l["color"], dashed=bool(l.get("dashed")),
            d=path_d(P), lx=round(lx, 1), ly=round(ly, 1), dx=l.get("label_dx", 0), dy=l.get("label_dy", 0),
            miles=round(l["dist"] / 1609.344), time=l.get("time_label") or fmt_h(l["dur"])))
    for m in markers:
        x, y = proj(m["lat"], m["lon"])
        out["markers"].append(dict(kind=m["kind"], label=m["label"], x=round(x, 1), y=round(y, 1),
            dx=m.get("dx", 8), dy=m.get("dy", 4), anchor=m.get("anchor", "start"), lat=round(m["lat"], 5), lon=round(m["lon"], 5)))
    tpl = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "RouteMap.tsx.tpl")).read()
    sys.stdout.write(tpl.replace("__DATA__", json.dumps(out, separators=(",", ":"))).replace("__TITLE__", cfg.get("title", "Route map")))

if __name__ == "__main__":
    main(sys.argv[1])
```
(The states file covers the US; for other regions swap STATES_URL for any GeoJSON of region outlines.)

## RouteMap.tsx.tpl
```tsx
// ---- RouteMap (generated; pure inline SVG, no network at view time) ----
type MapLeg = { id: string; label: string; color: string; dashed: boolean; d: string; lx: number; ly: number; dx: number; dy: number; miles: number; time: string };
type MapMarker = { kind: string; label: string; x: number; y: number; dx: number; dy: number; anchor: string; lat: number; lon: number };
type MapData = { width: number; height: number; states: string[]; legs: MapLeg[]; markers: MapMarker[] };
const MAP: MapData = __DATA__;

function RouteMap() {
  const t = useGrokTheme();
  const m = MAP;
  const mk = (k: string) => m.markers.filter((x) => x.kind === k);
  const col = (k: string) => (k === "ink" ? t.text.primary : k === "other" ? t.dataviz.other : t.dataviz.categorical[Number(k.slice(1))] ?? t.dataviz.other);
  return (
    <div>
      <svg viewBox={`0 0 ${m.width} ${m.height}`} style={{ width: "100%", height: "auto", display: "block", background: t.bg.subtle, borderRadius: 12, border: `1px solid ${t.border.default}` }} role="img" aria-label="__TITLE__">
        {m.states.map((d, i) => (<path key={i} d={d} fill={t.bg.base} stroke={t.border.strong} strokeWidth={1} strokeLinejoin="round" />))}
        {m.legs.filter((l) => !l.dashed).map((l) => (<path key={l.id} d={l.d} fill="none" stroke={col(l.color)} strokeWidth={4.5} strokeLinecap="round" strokeLinejoin="round" />))}
        {m.legs.filter((l) => l.dashed).map((l) => (<path key={l.id} d={l.d} fill="none" stroke={col(l.color)} strokeWidth={4} strokeDasharray="10 7" strokeLinecap="round" strokeLinejoin="round" />))}
        {mk("gas").map((g, i) => (<g key={"g" + i}><circle cx={g.x} cy={g.y} r={7} fill={t.dataviz.other} stroke={t.text.primary} strokeWidth={1.5} /><text x={g.x} y={g.y + 3.5} textAnchor="middle" fontSize={10} fontWeight={700} fill={t.text.primary}>G</text></g>))}
        {mk("poi").map((g, i) => (<circle key={"o" + i} cx={g.x} cy={g.y} r={6} fill={t.bg.base} stroke={t.text.primary} strokeWidth={2.5} />))}
        {mk("start").concat(mk("overnight"), mk("destination")).map((p, i) => (
          <g key={"p" + i}>
            {p.kind === "overnight" ? <rect x={p.x - 8} y={p.y - 8} width={16} height={16} rx={3} fill={t.text.primary} stroke={t.bg.base} strokeWidth={2.5} />
              : p.kind === "destination" ? <polygon points={`${p.x},${p.y - 11} ${p.x + 11},${p.y} ${p.x},${p.y + 11} ${p.x - 11},${p.y}`} fill={t.text.accent} stroke={t.bg.base} strokeWidth={2.5} />
              : <circle cx={p.x} cy={p.y} r={9} fill={t.text.success} stroke={t.bg.base} strokeWidth={2.5} />}
          </g>
        ))}
        {m.markers.map((p, i) => (
          <text key={"t" + i} x={p.x + p.dx} y={p.y + p.dy} textAnchor={p.anchor as "start" | "end" | "middle"} fontSize={p.kind === "gas" || p.kind === "poi" ? 12 : 15} fontWeight={p.kind === "gas" || p.kind === "poi" ? 500 : 700} fill={t.text.primary} stroke={t.bg.subtle} strokeWidth={4} paintOrder="stroke" style={{ fontFamily: t.font.family }}>{p.label}</text>
        ))}
        {m.legs.map((l) => {
          const txt = `${l.label} · ${l.miles} mi · ${l.time}`;
          const w = txt.length * 7.2 + 16, x = l.lx + l.dx, y = l.ly + l.dy;
          return (<g key={"lb" + l.id}><rect x={x - w / 2} y={y - 12} width={w} height={24} rx={6} fill={t.bg.elevated} stroke={col(l.color)} strokeWidth={2} /><text x={x} y={y + 4.5} textAnchor="middle" fontSize={13} fontWeight={600} fill={t.text.primary} style={{ fontFamily: t.font.family }}>{txt}</text></g>);
        })}
      </svg>
      <div style={{ display: "flex", flexWrap: "wrap", gap: "8px 20px", marginTop: 10, fontSize: 13, color: t.text.secondary, fontFamily: t.font.family }}>
        {m.legs.map((l) => (
          <span key={"lg" + l.id} style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
            <svg width={26} height={8}><line x1={1} y1={4} x2={25} y2={4} stroke={col(l.color)} strokeWidth={4} strokeLinecap="round" strokeDasharray={l.dashed ? "6 4" : undefined} /></svg>{l.label}
          </span>
        ))}
        <span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><svg width={14} height={14}><circle cx={7} cy={7} r={6} fill={t.text.success} /></svg>Start</span>
        <span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><svg width={14} height={14}><rect x={1} y={1} width={12} height={12} rx={2} fill={t.text.primary} /></svg>Overnight</span>
        <span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><svg width={14} height={14}><polygon points="7,0 14,7 7,14 0,7" fill={t.text.accent} /></svg>Destination</span>
        <span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><svg width={14} height={14}><circle cx={7} cy={7} r={6} fill={t.dataviz.other} stroke={t.text.primary} strokeWidth={1.5} /></svg>Gas stop</span>
        {mk("poi").length > 0 && <span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><svg width={14} height={14}><circle cx={7} cy={7} r={5} fill="none" stroke={t.text.primary} strokeWidth={2.5} /></svg>Scenic detour</span>}
      </div>
    </div>
  );
}
// ---- end RouteMap ----
```
